     1	//! The MHPCO price list: what each insurable item costs to cover, before any
     2	//! risk assessment or customer standing is taken into account.
     3	//!
     4	//! This is the catalog side of the office's knowledge. It changes when the
     5	//! MHPCO revises its prices or its building-block offer, independently of the
     6	//! underwriting rules that surcharge and discount a policy.
     7	
     8	use std::collections::BTreeMap;
     9	
    10	use crate::Item;
    11	
    12	const SWORD_BASE_PREMIUM: f64 = 100.0;
    13	const AMULET_BASE_PREMIUM: f64 = 60.0;
    14	const STAFF_BASE_PREMIUM: f64 = 80.0;
    15	const POTION_BASE_PREMIUM: f64 = 40.0;
    16	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
    17	const COMPONENT_BLOCK_SIZE: usize = 3;
    18	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
    19	
    20	/// Components are the small insurable parts the MHPCO lists apart from main
    21	/// items: they are priced per component and may form building blocks.
    22	fn is_component(item: &Item) -> bool {
    23	    matches!(item.item_type.as_str(), "rune" | "moonstone")
    24	}
    25	
    26	/// The MHPCO price list: the base premium each insurable main item carries.
    27	/// Components are not priced here; they are priced per building block.
    28	fn main_item_base_premium(item: &Item) -> f64 {
    29	    match item.item_type.as_str() {
    30	        "amulet" => AMULET_BASE_PREMIUM,
    31	        "staff" => STAFF_BASE_PREMIUM,
    32	        "potion" => POTION_BASE_PREMIUM,
    33	        _ => SWORD_BASE_PREMIUM,
    34	    }
    35	}
    36	
    37	/// A building block of alike components is offered at a special base premium.
    38	fn component_group_base_premium(count: usize) -> f64 {
    39	    if count == COMPONENT_BLOCK_SIZE {
    40	        COMPONENT_BLOCK_BASE_PREMIUM
    41	    } else {
    42	        count as f64 * COMPONENT_BASE_PREMIUM
    43	    }
    44	}
    45	
    46	/// Components are alike when they are of the very same type: the MHPCO reads
    47	/// "3 alike components" strictly, so runes and moonstones never share a block.
    48	fn alike_component_kind(item: &Item) -> &str {
    49	    item.item_type.as_str()
    50	}
    51	
    52	/// The base premium of all components in a policy: components of the same kind
    53	/// are counted together so that their building block can apply.
    54	fn components_base_premium(items: &[Item]) -> f64 {
    55	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    56	    for item in items.iter().filter(|item| is_component(item)) {
    57	        *counts.entry(alike_component_kind(item)).or_default() += 1;
    58	    }
    59	    counts.into_values().map(component_group_base_premium).sum()
    60	}
    61	
    62	/// The base premium of all main items in a policy, straight from the price list.
    63	fn main_items_base_premium(items: &[Item]) -> f64 {
    64	    items
    65	        .iter()
    66	        .filter(|item| !is_component(item))
    67	        .map(main_item_base_premium)
    68	        .sum()
    69	}
    70	
    71	/// The policy base premium: the sum of the base premiums of all insured items.
    72	pub(crate) fn policy_base_premium(items: &[Item]) -> f64 {
    73	    main_items_base_premium(items) + components_base_premium(items)
    74	}
    75	
    76	/// The base premium an item-specific modifier is measured against: the item's
    77	/// own listed price, which for a component is the per-component premium.
    78	pub(crate) fn item_base_premium(item: &Item) -> f64 {
    79	    if is_component(item) {
    80	        COMPONENT_BASE_PREMIUM
    81	    } else {
    82	        main_item_base_premium(item)
    83	    }
    84	}
