#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_item_list_costs_only_the_processing_fee() {
        let customer = Customer { years_with_mhpco: 0 };
        assert_eq!(quote(&customer, &[], 0), 5);
    }

    #[test]
    fn plain_sword_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item {
                item_type: "sword".to_string(),
                cursed: false,
                enchantment: 0,
            }];
        assert_eq!(quote(&customer, &items, 0), 115);
    }

    #[test]
    fn plain_amulet_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item {
                item_type: "amulet".to_string(),
                cursed: false,
                enchantment: 0,
            }];
        assert_eq!(quote(&customer, &items, 0), 71);
    }

    #[test]
    fn plain_staff_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item {
                item_type: "staff".to_string(),
                cursed: false,
                enchantment: 0,
            }];
        assert_eq!(quote(&customer, &items, 0), 93);
    }

    #[test]
    fn plain_potion_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item {
                item_type: "potion".to_string(),
                cursed: false,
                enchantment: 0,
            }];
        assert_eq!(quote(&customer, &items, 0), 49);
    }

    #[test]
    fn single_rune_uses_the_component_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item {
                item_type: "rune".to_string(),
                cursed: false,
                enchantment: 0,
            }];
        assert_eq!(quote(&customer, &items, 0), 33);
    }

    #[test]
    fn single_moonstone_uses_the_component_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item {
                item_type: "moonstone".to_string(),
                cursed: false,
                enchantment: 0,
            }];
